return {
	name = "viewbackpack",
	aliases = {"viewbp", "checktools", "viewtools", "toolview", "seetools"},
	fn = function(args, speaker)
	local target = getPlayer(args[1], speaker)
	local pl = target and target[1] and Players:FindFirstChild(target[1])
	if not pl then return end

	local bp = pl:FindFirstChildOfClass("Backpack")
	if not bp or not pl.Character then return end

	local t = {}
	local chartool = pl.Character:FindFirstChildOfClass("Tool")
	if chartool then -- include the tool the player is holding as well
		table.insert(t, chartool.Name)
	end

	for _, v in bp:GetChildren() do
		if v:IsA("Tool") then
			table.insert(t, v.Name)
		end
	end

	local title = ("%s's tools"):format(formatUsername(pl))
	if #t > 0 then
		notify(title, table.concat(t, ", "))
	else
		notify(title, "No tools.")
	end
end,
}
